"""Build the complete review from verified inventories and the existing viewer."""
from pathlib import Path
p=Path('tools/build-orc-combat-front-review.mjs').read_text(encoding='utf-8')
p=p.replace('orc-combat-front-validation-v1.json','orc-basic-complete-validation-v1.json').replace('orc-combat-front-editor-v1.json','orc-combat-directions-editor-v1.json')
p=p.replace('[r.state,{durationMs:',"[r.state+'_'+r.direction,{durationMs:")
p=p.replace('counts:{Attack:5,Hit:3,Defeat:5},durations:{Attack:90,Hit:80,Defeat:120}', 'counts:{Idle:4,Walk:6,Attack:5,Hit:3,Defeat:5},durations:{Idle:240,Walk:73,Attack:90,Hit:80,Defeat:120}')
p=p.replace('Orc — primeiro lote de combate','Orc — revisão completa das sete classes').replace('Orc — combate front_r','Orc — conjunto completo')
p=p.replace('<strong>Attack5, Hit3 e Defeat5 nas sete classes:</strong> 91 quadros novos e 21 clipes editáveis. As quatro vistas de Idle/Walk já estão aprovadas e foram preservadas. Revise este primeiro lote de combate antes das outras vistas.', '<strong>Idle, Walk, Attack, Hit e Defeat nas quatro vistas das sete classes.</strong> 679 PNGs e 168 fontes editáveis ativas. As vistas estáticas, a locomoção completa e o combate front_r já estão aprovados. Revise os 273 quadros novos de combate nas outras três vistas e a consistência do conjunto.')
p=p.replace('Total atual: 406 PNGs e 105 fontes editáveis ativas; faltam 273 quadros nas outras vistas de combate.', 'Inventário de corpo e roupa completo: 97 PNGs por classe. Armas independentes, projéteis, efeitos e extensões de runtime continuam pendentes.')
p=p.replace('<select id="state"><option>Attack</option>', '<select id="state"><option>Idle</option><option>Walk</option><option selected>Attack</option>')
p=p.replace('<label>Classe <select', '<label>Vista <select id="direction"><option>front_r</option><option selected>front_l</option><option>back_r</option><option>back_l</option></select></label><label>Classe <select')
p=p.replace('${c.clips.Attack.editable}', '${c.clips.Attack_front_r.editable}').replace('${c.clips.Attack.strip}', '${c.clips.Attack_front_r.strip}')
p=p.replace('/reports/combat-front-v1.json','/reports/complete-v1.json')
p=p.replace('Revisão artística pendente','Consistência final pendente')
p=p.replace("let current='Attack',playing=true", "let current='Attack',direction='front_l',playing=true")
p=p.replace("current=document.querySelector('#state').value;held=0", "current=document.querySelector('#state').value;direction=document.querySelector('#direction').value;held=0")
p=p.replace('clip=c.clips[current];',"clip=c.clips[current+'_'+direction];a.querySelector('.base').src=c.id+'/sprites/Directions/'+c.id.replaceAll('-','_')+'_dir_'+direction+'.png';")
p=p.replace("current==='Hit'?'Reação ao impacto':'Queda e derrota'", "current==='Hit'?'Reação ao impacto':current==='Defeat'?'Queda e derrota':current==='Walk'?'Caminhada':'Respiração sutil'")
p=p.replace("document.querySelector('#state').onchange=selectState;", "document.querySelector('#state').onchange=selectState;document.querySelector('#direction').onchange=selectState;")
p=p.replace('c.clips[current].frames[held]',"c.clips[current+'_'+direction].frames[held]")
p=p.replace("document.querySelector('#repeat').checked?frame%", "(document.querySelector('#repeat').checked||current==='Idle'||current==='Walk')?frame%")
p=p.replace('review-orc-combat-front-v1.html','review-orc-basic-complete-v1.html')
p=p.replace("console.log('Combat front_r preview:91 frames,21 clips,3 states,7 classes.');", "console.log('Complete preview:644 animation frames,140 clips,5 states,4 directions,7 classes.');")
Path('tools/build-orc-basic-complete-review.mjs').write_text(p,encoding='utf-8')
